//! Renders a `Config` into zsh or nushell source code.

use std::fmt::Write;

use crate::config::{Config, Shell, Value};
use crate::template::{self, Seg};

pub fn render(cfg: &Config, shell: Shell, source: &str) -> String {
    match shell {
        Shell::Zsh => zsh(cfg, source),
        Shell::Nu => nu(cfg, source),
    }
}

fn header(source: &str) -> String {
    format!(
        "# Generated by shellsync {} from {source}\n# Do not edit: changes are overwritten. Edit the source file instead.\n",
        env!("CARGO_PKG_VERSION")
    )
}

fn values(list: &[Value], shell: Shell) -> Vec<&str> {
    list.iter().filter_map(|v| v.get(shell)).collect()
}

// ---------------------------------------------------------------- zsh ----

/// `'...'` with embedded single quotes closed, escaped and reopened.
pub fn zsh_quote(s: &str) -> String {
    format!("'{}'", s.replace('\'', r"'\''"))
}

/// A double-quoted zsh word; template variables become `${NAME}`.
pub fn zsh_template(s: &str) -> String {
    let mut out = String::from("\"");
    for seg in template::parse(s) {
        match seg {
            Seg::Var(name) => write!(out, "${{{name}}}").unwrap(),
            Seg::Lit(lit) => {
                for c in lit.chars() {
                    if matches!(c, '\\' | '"' | '$' | '`') {
                        out.push('\\');
                    }
                    out.push(c);
                }
            }
        }
    }
    out.push('"');
    out
}

fn zsh(cfg: &Config, source: &str) -> String {
    let sh = Shell::Zsh;
    let mut out = header(source);

    for (name, v) in &cfg.env {
        if let Some(v) = v.get(sh) {
            writeln!(out, "export {name}={}", zsh_template(v)).unwrap();
        }
    }

    let pre = values(&cfg.path_prepend, sh);
    let post = values(&cfg.path_append, sh);
    if !pre.is_empty() || !post.is_empty() {
        // -U keeps the first occurrence, so prepended entries move to the front.
        out.push_str("typeset -gU path\n");
        let mut words: Vec<String> = pre.iter().map(|p| zsh_template(p)).collect();
        words.push("$path".into());
        words.extend(post.iter().map(|p| zsh_template(p)));
        writeln!(out, "path=({})", words.join(" ")).unwrap();
    }

    for (name, v) in &cfg.aliases {
        if let Some(body) = v.get(sh) {
            writeln!(out, "alias -- {name}={}", zsh_quote(body)).unwrap();
        }
    }

    push_raw(&mut out, &cfg.zsh_init);
    out
}

// ----------------------------------------------------------------- nu ----

/// A nushell string literal that needs no escaping: `'...'` when possible,
/// otherwise a raw string `r#'...'#` with enough `#`s.
pub fn nu_quote(s: &str) -> String {
    if !s.contains('\'') {
        return format!("'{s}'");
    }
    let mut hashes = String::from("#");
    while s.contains(&format!("'{hashes}")) {
        hashes.push('#');
    }
    format!("r{hashes}'{s}'{hashes}")
}

fn nu_var(name: &str) -> String {
    if name == "PATH" {
        // $env.PATH is a list in nushell; flatten it the way other shells see it.
        "($env.PATH | split row (char esep) | str join (char esep))".into()
    } else {
        format!("($env.{name}? | default '')")
    }
}

fn nu_template(s: &str) -> String {
    let parts: Vec<String> = template::parse(s)
        .into_iter()
        .map(|seg| match seg {
            Seg::Lit(lit) => nu_quote(&lit),
            Seg::Var(name) => nu_var(&name),
        })
        .collect();
    match parts.len() {
        0 => "''".into(),
        1 => parts.into_iter().next().unwrap(),
        _ => format!("([{}] | str join)", parts.join(" ")),
    }
}

fn nu(cfg: &Config, source: &str) -> String {
    let sh = Shell::Nu;
    let mut out = header(source);

    for (name, v) in &cfg.env {
        if let Some(v) = v.get(sh) {
            writeln!(out, "$env.{name} = {}", nu_template(v)).unwrap();
        }
    }

    let pre = values(&cfg.path_prepend, sh);
    let post = values(&cfg.path_append, sh);
    if !pre.is_empty() || !post.is_empty() {
        let list = |l: &[&str]| {
            l.iter()
                .map(|p| nu_template(p))
                .collect::<Vec<_>>()
                .join(" ")
        };
        let mut expr = String::from("$env.PATH | split row (char esep)");
        if !pre.is_empty() {
            write!(expr, " | prepend [{}]", list(&pre)).unwrap();
        }
        if !post.is_empty() {
            write!(expr, " | append [{}]", list(&post)).unwrap();
        }
        writeln!(out, "$env.PATH = ({expr} | uniq)").unwrap();
    }

    for (name, v) in &cfg.aliases {
        if let Some(body) = v.get(sh) {
            writeln!(out, "alias {name} = {}", body.trim()).unwrap();
        }
    }

    push_raw(&mut out, &cfg.nu_init);
    out
}

fn push_raw(out: &mut String, code: &str) {
    if !code.trim().is_empty() {
        out.push_str("\n# --- init ---\n");
        out.push_str(code.trim_matches('\n'));
        out.push('\n');
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn body(cfg: &str, shell: Shell) -> String {
        let out = render(&Config::parse(cfg).unwrap(), shell, "test");
        out.lines().skip(2).collect::<Vec<_>>().join("\n")
    }

    #[test]
    fn zsh_quoting() {
        assert_eq!(zsh_quote("it's"), r"'it'\''s'");
        assert_eq!(
            zsh_template(r#"~/a "b" $$c `d` \e"#),
            r#""${HOME}/a \"b\" \$c \`d\` \\e""#
        );
    }

    #[test]
    fn nu_quoting() {
        assert_eq!(nu_quote("plain"), "'plain'");
        assert_eq!(nu_quote("it's"), "r#'it's'#");
        assert_eq!(nu_quote("a'#b"), "r##'a'#b'##");
        assert_eq!(nu_template(""), "''");
        assert_eq!(nu_template("$HOME"), "($env.HOME? | default '')");
        assert_eq!(
            nu_template("~/x"),
            "([($env.HOME? | default '') '/x'] | str join)"
        );
    }

    #[test]
    fn renders_zsh() {
        let cfg = r#"
            [env]
            GOPATH = "~/go"
            ONLY_NU = { nu = "x" }
            [path]
            prepend = ["$GOPATH/bin"]
            append = ["/opt/bin"]
            [aliases]
            g = "git"
            q = "echo 'hi'"
            [zsh]
            init = "\nsetopt autocd\n"
        "#;
        assert_eq!(
            body(cfg, Shell::Zsh),
            [
                r#"export GOPATH="${HOME}/go""#,
                "typeset -gU path",
                r#"path=("${GOPATH}/bin" $path "/opt/bin")"#,
                "alias -- g='git'",
                r"alias -- q='echo '\''hi'\'''",
                "",
                "# --- init ---",
                "setopt autocd",
            ]
            .join("\n")
        );
    }

    #[test]
    fn renders_nu() {
        let cfg = r#"
            [env]
            EDITOR = "nvim"
            ONLY_ZSH = { zsh = "x" }
            [path]
            prepend = ["/a", "/b"]
            [aliases]
            ll = { zsh = "ls -lh", nu = "ls -l" }
        "#;
        assert_eq!(
            body(cfg, Shell::Nu),
            [
                "$env.EDITOR = 'nvim'",
                "$env.PATH = ($env.PATH | split row (char esep) | prepend ['/a' '/b'] | uniq)",
                "alias ll = ls -l",
            ]
            .join("\n")
        );
    }

    #[test]
    fn empty_config_is_just_a_header() {
        assert_eq!(body("", Shell::Zsh), "");
        assert_eq!(body("", Shell::Nu), "");
    }
}
